// Shared helpers for the line-splitting / diff-gate dimension.
import { run } from './drv.mjs';

// Parse the single-line dict output into {new_value, old_value, diff} raw Python reprs.
export function parse(out) {
  const s = out.replace(/\n$/, '');
  if (s === '{}') return { empty: true };
  if (!s.startsWith("{'values_changed': {'root': {")) return { unparsed: s };
  const inner = s.slice("{'values_changed': {'root': {".length, -3);
  // keys are in fixed order: new_value, old_value, [diff]
  const res = { keys: [] };
  const dIdx = inner.indexOf(", 'diff': ");
  let head = inner, diff = null;
  if (dIdx !== -1) { head = inner.slice(0, dIdx); diff = inner.slice(dIdx + ", 'diff': ".length); }
  const oIdx = head.indexOf(", 'old_value': ");
  const nv = head.slice("'new_value': ".length, oIdx);
  const ov = head.slice(oIdx + ", 'old_value': ".length);
  res.new_value = nv; res.old_value = ov; res.diff = diff;
  res.keys = diff === null ? ['new_value', 'old_value'] : ['new_value', 'old_value', 'diff'];
  return res;
}

// Decode a Python str repr (single- or double-quoted) into a JS string.
export function unrepr(r) {
  if (r == null) return null;
  const q = r[0];
  let body = r.slice(1, -1);
  let out = '';
  for (let i = 0; i < body.length; i++) {
    const c = body[i];
    if (c !== '\\') { out += c; continue; }
    const n = body[++i];
    if (n === 'n') out += '\n';
    else if (n === 'r') out += '\r';
    else if (n === 't') out += '\t';
    else if (n === '\\') out += '\\';
    else if (n === "'") out += "'";
    else if (n === '"') out += '"';
    else if (n === 'a') out += '';
    else if (n === 'b') out += '\b';
    else if (n === 'f') out += '\f';
    else if (n === 'v') out += '\v';
    else if (n === '0') out += '\0';
    else if (n === 'x') { out += String.fromCharCode(parseInt(body.substr(i + 1, 2), 16)); i += 2; }
    else if (n === 'u') { out += String.fromCharCode(parseInt(body.substr(i + 1, 4), 16)); i += 4; }
    else if (n === 'U') { out += String.fromCodePoint(parseInt(body.substr(i + 1, 8), 16)); i += 8; }
    else out += '\\' + n;
  }
  return out;
}

export function probe(a, b) {
  const r = run(a, b);
