// Shared helpers. NOTE: zero backslash escapes inside string literals on purpose.
import { run } from './drv.mjs';

export const C = (n) => String.fromCodePoint(n);
export const BSL = C(92);   // backslash
export const LF = C(10);
export const CR = C(13);
export const SQ = C(39);
export const DQ = C(34);

const PREFIX = "{" + SQ + "values_changed" + SQ + ": {" + SQ + "root" + SQ + ": {";
const K_NEW = SQ + "new_value" + SQ + ": ";
const K_OLD = ", " + SQ + "old_value" + SQ + ": ";
const K_DIFF = ", " + SQ + "diff" + SQ + ": ";

export function parse(out) {
  let s = out;
  while (s.length && s[s.length - 1] === LF) s = s.slice(0, -1);
  if (s === "{}") return { empty: true, keys: [] };
  if (!s.startsWith(PREFIX) || !s.endsWith("}}}")) return { unparsed: s, keys: [] };
  const inner = s.slice(PREFIX.length, -3);
  const dIdx = inner.lastIndexOf(K_DIFF);
  let head = inner, diff = null;
  if (dIdx !== -1) { head = inner.slice(0, dIdx); diff = inner.slice(dIdx + K_DIFF.length); }
  const oIdx = head.lastIndexOf(K_OLD);
  const nv = head.slice(K_NEW.length, oIdx);
  const ov = head.slice(oIdx + K_OLD.length);
  return { new_value: nv, old_value: ov, diff,
           keys: diff === null ? ["new_value", "old_value"] : ["new_value", "old_value", "diff"] };
}

const SIMPLE = { n: 10, r: 13, t: 9, a: 7, b: 8, f: 12, v: 11, "0": 0 };

// Decode a Python str repr into a real JS string.
export function unrepr(r) {
  if (r == null) return null;
