  const p = probe(a, "");
  if (!p.diffStr) return { err: "no diff key", p };
  const dl = p.diffStr.split(LF);
  if (dl[0] !== "--- " || dl[1] !== "+++ ") return { err: "bad header " + show(dl.slice(0, 3)) };
  if (!/^@@ -1(,\d+)? \+0,0 @@$/.test(dl[2])) return { err: "bad hunk " + show(dl[2]) };
  const body = dl.slice(3);
  for (const l of body) if (l[0] !== "-") return { err: "non-del line " + show(l) };
  return { lines: body.map((l) => l.slice(1)) };
}

const eq = (x, y) => x.length === y.length && x.every((v, i) => v === y[i]);

