const foundBoundaries = new Set();

function scan(cps, label) {
  const a = LF + cps.map((cp) => "z" + C(cp)).join("") + "z";
  const got = actualLines(a);
  runs++;
  if (got.err) { console.log("ERR", label, got.err); bad++; return; }
  const want = splitLines(a);
  if (!eq(got.lines, want)) {
    bad++;
    console.log("MISMATCH batch", label);
    console.log("  want(%d)=%s", want.length, show(want).slice(0, 400));
    console.log("  got (%d)=%s", got.lines.length, show(got.lines).slice(0, 400));
  }
  // independent derivation: any cp adjacent to a line break in `got`
  // reconstruct by walking got.lines: each line ends where a boundary was
  let flat = got.lines.join("|");
  for (const cp of cps) if (!flat.includes("z" + C(cp) + "z")) foundBoundaries.add(cp);
}

