const BATCH = 600;
let batch = [];
const t0 = Date.now();
for (let cp = 1; cp <= 0xffff; cp++) {
  if (cp >= 0xd800 && cp <= 0xdfff) continue;
  batch.push(cp);
  if (batch.length === BATCH) { scan(batch, "U+" + batch[0].toString(16)); batch = []; }
